// Normaliza Wazuh, OPNsense o un payload genérico.
const input = $input.first().json;
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const rule = body.rule || {};
const agent = body.agent || {};
const data = body.data || {};
const level = Math.max(0, Math.min(15, Number(rule.level ?? body.rule_level ?? body.level ?? 5)));
const severity = level >= 12 ? 'critical' : level >= 9 ? 'high' : level >= 6 ? 'medium' : level >= 3 ? 'low' : 'info';
const source = body.source || (rule.id ? 'wazuh' : (body.src_ip || body.dest_ip) ? 'opnsense' : 'generic');
const title = String(rule.description || body.title || body.event || body.message || 'Alerta de seguridad').slice(0, 300);
const description = String(body.full_log || body.description || body.message || '').slice(0, 8000);
const srcip = data.srcip || body.src_ip || body.source_ip || null;
const dstip = data.dstip || body.dest_ip || body.destination_ip || null;
const hostname = agent.name || body.hostname || body.host || null;
const username = data.dstuser || data.srcuser || body.username || body.user || null;
const externalId = body.id || body.event_id || body.alert_id || null;
const occurredAt = body.timestamp || body['@timestamp'] || body.event_time || new Date().toISOString();
const parsed = new Date(occurredAt);
const iso = Number.isNaN(parsed.getTime()) ? new Date().toISOString() : parsed.toISOString();
const bucket = Math.floor(new Date(iso).getTime() / 300000);
const material = [source, externalId || '', title.trim().toLowerCase(), srcip || '', hostname || '', bucket].join('|');
let hash = 1469598103934665603n;
for (const char of material) { hash ^= BigInt(char.codePointAt(0)); hash = BigInt.asUintN(64, hash * 1099511628211n); }
const fingerprint = hash.toString(16).padStart(16, '0') + '-' + bucket.toString(16);
return [{ json: {
  external_id: externalId,
  fingerprint,
  source,
  title,
  description,
  rule_id: String(rule.id || body.rule_id || ''),
  rule_level: level,
  severity,
  source_ip: srcip,
  destination_ip: dstip,
  hostname,
  agent_name: hostname,
  username,
  mitre_techniques: Array.isArray(body.mitre) ? body.mitre : [],
  tags: [source],
  raw_payload: body,
  received_at: iso
} }];
